class EdgeEmbeddingEngine:
    PREFIX = "Represent this sentence: "
    OVERHEAD_MB = 50

    def __init__(self, model_size_mb=33):
        self.model_size_mb = model_size_mb
        self.quantized = False

    def quantize(self):
        if self.quantized:
            return
        self.model_size_mb = self.model_size_mb / 4
        self.quantized = True

    def encode(self, text: str) -> dict:
        text = text.lower()
        vec = {}
        for i in range(len(text) - 2):
            tri = text[i:i + 3]
            vec[tri] = vec.get(tri, 0) + 1
        return vec

    def encode_with_prefix(self, text: str) -> dict:
        return self.encode(self.PREFIX + text)

    def fits_on_device(self, device_ram_mb: int) -> bool:
        return self.model_size_mb + self.OVERHEAD_MB <= device_ram_mb


# Test it:
engine = EdgeEmbeddingEngine()
print(engine.model_size_mb)
print(engine.fits_on_device(256))

engine.quantize()
print(engine.model_size_mb)
print(engine.quantized)

vec = engine.encode("hello world")
print(len(vec) > 0)

prefixed = engine.encode_with_prefix("lights off")
print("rep" in prefixed)

import math

class EdgeEmbeddingEngine:
    def __init__(self, model_size_mb=33):
        self.model_size_mb = model_size_mb
        self.quantized = False

    def quantize(self):
        if not self.quantized:
            self.model_size_mb /= 4
            self.quantized = True

    def encode(self, text):
        t = text.lower()
        vec = {}
        for i in range(len(t) - 2):
            tri = t[i:i+3]
            vec[tri] = vec.get(tri, 0) + 1
        return vec

    def encode_with_prefix(self, text):
        return self.encode("Represent this sentence: " + text)

class HomieCommandMatcher:
    def __init__(self):
        self.engine = EdgeEmbeddingEngine()
        self.commands = {}     # description -> action
        self.cmd_vectors = {}  # description -> trigram dict
        self.total_queries = 0
        self.successful_matches = 0

    def register_commands(self, command_map: dict):
        for desc, action in command_map.items():
            self.commands[desc] = action
            self.cmd_vectors[desc] = self.engine.encode(desc)

    def _cosine_similarity(self, vec_a: dict, vec_b: dict) -> float:
        mag_a = math.sqrt(sum(v * v for v in vec_a.values()))
        mag_b = math.sqrt(sum(v * v for v in vec_b.values()))
        if mag_a == 0 or mag_b == 0:
            return 0.0
        dot = sum(v * vec_b.get(k, 0) for k, v in vec_a.items())
        return float(dot / (mag_a * mag_b))

    def match(self, utterance: str, threshold: float = 0.3) -> dict:
        self.total_queries += 1
        q = self.engine.encode_with_prefix(utterance)
        best_action = "unknown"
        best_score = 0.0
        for desc, vec in self.cmd_vectors.items():
            score = self._cosine_similarity(q, vec)
            if score > best_score:
                best_score = score
                best_action = self.commands[desc]
        if best_score >= threshold and best_score > 0:
            self.successful_matches += 1
            return {"action": best_action, "confidence": float(best_score), "matched": True}
        return {"action": "unknown", "confidence": float(best_score), "matched": False}

    def stats(self) -> dict:
        acc = self.successful_matches / self.total_queries if self.total_queries else 0.0
        return {
            "total_queries": self.total_queries,
            "successful_matches": self.successful_matches,
            "accuracy": float(acc),
        }

# Test it:
homie = HomieCommandMatcher()
homie.register_commands({
    "turn on the lights": "lights.on",
    "play some music": "speaker.play",
    "lock the door": "door.lock",
})

r = homie.match("switch on the light")
print(r["matched"])
print(r["action"])

s = homie.stats()
print(s["total_queries"])
print(s["successful_matches"])
